import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const ListaCurso = () => {
  const { id } = useParams(); // Obtém o ID do aluno da URL
  const navigate = useNavigate();
  const [aluno, setAluno] = useState(null);
  const [cursosAluno, setCursosAluno] = useState([]);
  const [professores, setProfessores] = useState({});
  const [loading, setLoading] = useState(true);
  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");

  // Busca os cursos do aluno e informações dos professores
  const fetchCursosAluno = async () => {
    try {
      const resposta = await private_api.get(`/alunos/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursosAluno(resposta.data);

        // Busca informações dos professores para cada curso
        const professoresMap = {};
        for (const curso of resposta.data) {
          if (curso.professorId && !professoresMap[curso.professorId]) {
            try {
              const profResposta = await private_api.get(
                `/professores/${curso.professorId}`
              );
              if (profResposta.status === 200) {
                professoresMap[curso.professorId] =
                  profResposta.data.utilizador;
              }
            } catch (error) {
              console.error(
                `Erro ao buscar professor ${curso.professorId}:`,
                error
              );
            }
          }
        }
        setProfessores(professoresMap);
      }
    } catch (error) {
      console.error("Erro ao buscar cursos do aluno:", error);
    }
  };

  // Busca informações do aluno
  const fetchAluno = async () => {
    try {
      const resposta = await private_api.get(`/alunos/${id}`);
      if (resposta.status === 200) {
        setAluno(resposta.data);
      }
    } catch (error) {
      console.error("Erro ao buscar aluno:", error);
    } finally {
      setLoading(false);
    }
  };

  // Busca comentários
  const fetchComentarios = async () => {
    try {
      const response = await private_api.get("/comentarios");
      setComentarios(response.data);
    } catch (err) {
      console.error("Erro ao carregar comentários:", err);
    }
  };

  const handleComentarioClick = () => {
    setShowComentarioModal(true);
  };

  const handleSubmitComentario = async () => {
    if (!novoComentario.trim()) {
      alert("Por favor, escreva um comentário antes de enviar.");
      return;
    }

    try {
      const response = await private_api.post("/comentarios", {
        conteudo: novoComentario,
      });

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      if (err.response?.status === 401) {
        alert("Sessão expirada. Por favor, faça login novamente.");
        navigate("/login");
      } else {
        alert(
          err.response?.data?.message ||
            "Erro ao enviar comentário. Por favor, tente novamente."
        );
      }
    }
  };

  useEffect(() => {
    fetchAluno();
    fetchCursosAluno();
    fetchComentarios();
  }, [id]);

  if (loading) {
    return (
      <div
        className="container-fluid d-flex flex-column align-items-center justify-content-center"
        style={{ backgroundColor: "#E7EFF4", minHeight: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (!aluno) {
    return (
      <div
        className="container-fluid d-flex flex-column align-items-center justify-content-center"
        style={{ backgroundColor: "#E7EFF4", minHeight: "100vh" }}
      >
        <div className="alert alert-danger">Aluno não encontrado</div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <div className="bg-white w-75 p-2 d-flex justify-content-center">
        <nav className="nav nav-tabs">
          <a className="nav-link active mx-3" href="">
            Cursos
          </a>
          <a
            className="nav-link mx-3"
            href=""
            onClick={() => navigate(`/aula/${id}`)}
          >
            Aulas
          </a>
          <a
            className="nav-link mx-3"
            href=""
            onClick={() => navigate(`/avaliacao/${id}`)}
          >
            Avaliações
          </a>
        </nav>
      </div>

      <div className="d-flex justify-content-between align-items-center w-75 mb-3">
        <h2>Cursos de {aluno.utilizador.nome}</h2>
      </div>

      <table className="table table-bordered bg-white w-75">
        <thead>
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
            <th>Professor</th>
          </tr>
        </thead>
        <tbody>
          {cursosAluno.length > 0 ? (
            cursosAluno.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                <td>{curso.periodo === "manha" ? "Manhã" : "Tarde"}</td>
                <td>{professores[curso.professorId]?.nome || "N/A"}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="6" className="text-center">
                Este aluno não está inscrito em nenhum curso
              </td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Seção de Comentários */}
      <div className="card p-3 w-75 mt-4">
        <h4>Testemunhos de Alunos:</h4>
        {comentarios.length > 0 ? (
          comentarios.map((comentario) => (
            <div key={comentario.id} className="mb-3 border-bottom pb-2">
              <h5>{comentario.aluno?.utilizador?.nome || "Anônimo"}:</h5>
              <p>{comentario.conteudo}</p>
              <small className="text-muted">
                {new Date(comentario.dataPublicacao).toLocaleDateString(
                  "pt-PT",
                  {
                    day: "2-digit",
                    month: "2-digit",
                    year: "numeric",
                    hour: "2-digit",
                    minute: "2-digit",
                  }
                )}
              </small>
            </div>
          ))
        ) : (
          <p>Nenhum comentário ainda. Seja o primeiro a comentar!</p>
        )}

        <div className="mt-3">
          <button
            className="btn btn-outline-primary"
            onClick={handleComentarioClick}
          >
            Deixar um comentário
          </button>
        </div>
      </div>

      {/* Modal para novo comentário */}
      {showComentarioModal && (
        <div
          className="modal"
          style={{
            display: "block",
            backgroundColor: "rgba(0,0,0,0.5)",
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 1050,
          }}
        >
          <div className="modal-dialog modal-dialog-centered">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Novo Comentário</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowComentarioModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <textarea
                  className="form-control"
                  rows="4"
                  value={novoComentario}
                  onChange={(e) => setNovoComentario(e.target.value)}
                  placeholder="Escreva seu comentário aqui..."
                ></textarea>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowComentarioModal(false)}
                >
                  Cancelar
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleSubmitComentario}
                  disabled={!novoComentario.trim()}
                >
                  Enviar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="card p-3 w-75 mt-4">
        <div className="d-flex justify-content-between align-items-center">
          <span>Inscrever-se em um Curso</span>
          <button
            className="btn btn-link"
            onClick={() => navigate(`/alunodetalhes/${id}`)}
          >
            Ver Detalhes
          </button>
        </div>
      </div>
    </div>
  );
};

export default ListaCurso;
